//! Unicode properties used by the native tokenizer port.
//!
//! The ranges and canonical-composition data are generated from Python's
//! Unicode database and are covered by the Unicode license in
//! THIRD_PARTY_NOTICES.md. The tokenizer only needs the properties below;
//! keeping them local avoids a runtime dependency on a native Unicode crate.

const std = @import("std");

pub const Range = struct { first: u21, last: u21 };
pub const CombiningRange = struct { first: u21, last: u21, class: u8 };
pub const Decomposition = struct { cp: u21, parts: [3]u21, len: u2 };
pub const Composition = struct { pair: u64, cp: u21 };
pub const Lower = struct { cp: u21, bytes: [12]u8, len: u4 };

fn contains(ranges: []const Range, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const range = ranges[mid];
        if (cp < range.first) hi = mid else if (cp > range.last) lo = mid + 1 else return true;
    }
    return false;
}
fn group(cp: u21, ranges: []const Range) bool {
    return contains(ranges, cp);
}

