pub const han_ranges = [_]Range{
    .{ .first = 0x3400, .last = 0x4dbf },
    .{ .first = 0x4e00, .last = 0x9fff },
    .{ .first = 0xf900, .last = 0xfaff },
    .{ .first = 0x20000, .last = 0x2a6df },
    .{ .first = 0x2a700, .last = 0x2ceaf },
};

pub fn isLetter(cp: u21) bool {
    return group(cp, &letter_ranges);
}
pub fn isNumber(cp: u21) bool {
    return group(cp, &number_ranges);
}
pub fn isMark(cp: u21) bool {
    return group(cp, &mark_ranges);
}
pub fn isPunctuation(cp: u21) bool {
    return group(cp, &punctuation_ranges);
}
pub fn isSymbol(cp: u21) bool {
    return group(cp, &symbol_ranges);
}
pub fn isSeparator(cp: u21) bool {
    return group(cp, &separator_ranges);
}
pub fn isWhitespace(cp: u21) bool {
    return group(cp, &whitespace_ranges);
}
pub fn isUpper(cp: u21) bool {
    return group(cp, &upper_ranges);
}
pub fn isLower(cp: u21) bool {
    return group(cp, &lower_ranges);
}
pub fn isModifierLetter(cp: u21) bool {
    return group(cp, &modifier_letter_ranges);
}
pub fn isOtherLetter(cp: u21) bool {
    return group(cp, &other_letter_ranges);
}
pub fn isFormat(cp: u21) bool {
    return group(cp, &format_ranges);
}
pub fn isUnassigned(cp: u21) bool {
    return group(cp, &unassigned_ranges);
}
pub fn isHan(cp: u21) bool {
    return group(cp, &han_ranges);
}
pub fn generalCategoryGroup(cp: u21) enum { letter, mark, number, punctuation, symbol, separator, other } {
    if (isLetter(cp)) return .letter;
    if (isMark(cp)) return .mark;
    if (isNumber(cp)) return .number;
    if (isPunctuation(cp)) return .punctuation;
    if (isSymbol(cp)) return .symbol;
    if (isSeparator(cp)) return .separator;
    return .other;
}

