pub fn combiningClass(cp: u21) u8 {
    var lo: usize = 0;
    var hi: usize = combining_ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = combining_ranges[mid];
        if (cp < r.first) hi = mid else if (cp > r.last) lo = mid + 1 else return r.class;
    }
    return 0;
}
pub fn isCombining9(cp: u21) bool {
    return combiningClass(cp) == 9;
}

