        const mid = lo + (hi - lo) / 2;
        const item = decomposition[mid];
        if (cp < item.cp) hi = mid else if (cp > item.cp) lo = mid + 1 else return item;
    }
    return null;
}
pub fn compose(pair: u64) ?u21 {
    var lo: usize = 0;
    var hi: usize = composition.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const item = composition[mid];
        if (pair < item.pair) hi = mid else if (pair > item.pair) lo = mid + 1 else return item.cp;
    }
    return null;
}
pub fn lowerBytes(cp: u21) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = lower.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const item = lower[mid];
        if (cp < item.cp) hi = mid else if (cp > item.cp) lo = mid + 1 else return item.bytes[0..item.len];
    }
    return null;
}
